all_features:
def feature(text: str) -> float:
    "Count of numeric characters in the text"
    return float(sum(1 for c in text if c.isdigit()))

def feature(text: str) -> float:
    "Ratio of unique words to total word count"
    words = text.split()
    unique_words = len(set(words))
    return unique_words / len(words) if words else 0.0

def feature(text: str) -> float:
    "Average sentence length in words"
    sentences = re.split(r'[.!?]+', text)
    lengths = [len(s.split()) for s in sentences if s.split()]
    return float(sum(lengths) / len(lengths)) if lengths else 0.0

def feature(text: str) -> float:
    "Count of punctuation marks in the text"
    punctuation_count = sum(1 for c in text if c in string.punctuation)
    return float(punctuation_count)

def feature(text: str) -> float:
    "Average character length of words in the text"
    words = text.split()
    total_length = sum(len(word) for word in words)
    return total_length / len(words) if words else 0.0

def feature(text: str) -> float:
    "Percentage of stopwords in the text"
    doc = nlp(text)
    stopword_count = sum(1 for token in doc if token.is_stop)
    return stopword_count / len(doc) if len(doc) > 0 else 0.0

def feature(text: str) -> float:
    "Count of named entities in the text"
    doc = nlp(text)
    return float(len(doc.ents))

def feature(text: str) -> float:
    "Flesch reading ease score of the text"
    import textstat
    return float(textstat.flesch_reading_ease(text))

def feature(text: str) -> float:
    "Count of adverbs in the text"
    doc = nlp(text)
    adverb_count = sum(1 for token in doc if token.pos_ == 'ADV')
    return float(adverb_count)

def feature(text: str) -> float:
    "Ratio of questions to total sentences"
    sentences = re.split(r'[.!?]+', text)
    question_count = sum(1 for s in sentences if '?' in s)
    return question_count / len(sentences) if sentences else 0.0
def feature(text: str) -> float:
    "Estimated readability using the Gunning Fog Index"
    import textstat
    return float(textstat.gunning_fog(text))

def feature(text: str) -> float:
    "Count of unique named entities in the text"
    doc = nlp(text)
    unique_entities = len(set(ent.text for ent in doc.ents))
    return float(unique_entities)

def feature(text: str) -> float:
    "Average sentiment polarity of the text"
    scores = sia.polarity_scores(text)
    return float(scores['compound'])

def feature(text: str) -> float:
    "Ratio of long words (greater than 7 characters) to total words"
    words = text.split()
    long_word_count = sum(1 for word in words if len(word) > 7)
    return long_word_count / len(words) if words else 0.0

def feature(text: str) -> float:
    "Count of verbs in the text"
    doc = nlp(text)
    verb_count = sum(1 for token in doc if token.pos_ == 'VERB')
    return float(verb_count)

def feature(text: str) -> float:
    "Average length of sentences in characters"
    sentences = re.split(r'[.!?]+', text)
    lengths = [len(s) for s in sentences if s.strip()]
    return float(sum(lengths) / len(lengths)) if lengths else 0.0

def feature(text: str) -> float:
    "Total number of characters in the text excluding spaces"
    return float(len(text.replace(' ', '')))

def feature(text: str) -> float:
    "Percentage of adverbs in total words"
    doc = nlp(text)
    adverb_count = sum(1 for token in doc if token.pos_ == 'ADV')
    return adverb_count / len(doc) if len(doc) > 0 else 0.0

def feature(text: str) -> float:
    "Mean character count of named entities"
    doc = nlp(text)
    entity_lengths = [len(ent.text) for ent in doc.ents]
    return float(statistics.mean(entity_lengths)) if entity_lengths else 0.0

def feature(text: str) -> float:
    "Count of complex words (three or more syllables)"
    import textstat
    complex_word_count = sum(1 for word in text.split() if textstat.syllable_count(word) >= 3)
    return float(complex_word_count)
